contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);
        c.addToBalance{value: deposit}(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterEth = address(c).balance;

        assert(!reverted && afterBal == 0 && afterEth + beforeBal == beforeEth);
    }

    receive() external payable {}
}

