pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        try c.addToBalance{value: deposit}() {} catch { return; }
        uint256 beforeBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeEth = address(c).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        uint afterEth = address(c).balance;
        assertTrue(!reverted && afterBal == 0 && afterEth + beforeBal == beforeEth);
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
